
(() => {
  'use strict';

  const normalize = (value = '') =>
    value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

  const spellDescriptions = {"Absorver Elementos": {"school": "1º nível de Abjuração", "time": "1 reação, que você faz quando sofre dano de ácido, frio, fogo, elétrico ou trovejante", "range": "Pessoal", "components": "S", "duration": "1 rodada", "description": ["A magia reverte parte da energia recebida, minimizando seu efeito em você e armazenando-a no seu próximo ataque corpo a corpo.", "Você tem resistência ao tipo de dano pertinente, incluindo o ataque que desencadeou a magia, até o início do seu próximo turno.", "Além disso, da primeira vez que você atingir um ataque corpo a corpo no seu próximo turno, o alvo sofre 1d6 de dano extra do tipo relacionado, e a magia termina."], "higher": "Quando você conjura essa magia usando um espaço de magia de 2º nível ou superior, o dano extra aumenta em 1d6 para cada nível do espaço acima do 1º."}, "Laço": {"school": "1º nível de Abjuração", "time": "1 minuto", "range": "Toque", "components": "S, M (7,5 metros de corda, que a magia consome)", "duration": "8 horas", "description": ["Ao conjurar esta magia, você usa a corda para criar um círculo com um raio de 1,5 metro no chão. Quando você termina a conjuração, a corda desaparece e o círculo torna-se uma armadilha mágica.", "Esta armadilha é quase invisível, exigindo uma verificação de Inteligência (Investigação) bem-sucedida contra sua CD de resistência mágica para ser discernida.", "A armadilha dispara quando uma criatura Pequena, Média ou Grande se move para o chão no raio da magia. Essa criatura deve ter sucesso em um teste de resistência de Destreza ou será magicamente presa no ar, deixando-a pendurada de cabeça para baixo a 90 centímetros acima do chão. A criatura é retida lá até a magia terminar.", "Uma criatura retida pode fazer um teste de resistência de Destreza no final de cada um de seus turnos, terminando o efeito sobre si mesma em um sucesso.", "Alternativamente, a criatura ou outra pessoa que possa alcançá-la pode usar uma ação para fazer uma verificação de Inteligência (Arcanismo) contra sua CD de resistência mágica. Em um sucesso, o efeito de retenção termina.", "Depois que a armadilha é disparada, a magia termina quando nenhuma criatura está retida por ela."]}, "Tremor de Terra": {"school": "1º nível de Evocação", "time": "1 ação", "range": "Pessoal", "components": "V, S", "duration": "Instantânea", "description": ["Você provoca um tremor no solo num raio de 3 metros. Cada criatura diferente de você na área deve realizar um teste de resistência de Destreza.", "Se falhar na resistência, uma criatura sofre 1d6 de dano de concussão e fica caída no chão.", "Se o solo na área for de terra ou pedra solta, ele se torna terreno difícil até ser limpo."], "higher": "Quando você conjura essa magia usando um espaço de magia de 2º nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 1º."}, "Vínculo com a Besta": {"school": "1º nível de Adivinhação", "time": "1 ação", "range": "Toque", "components": "V, S, M (um tufo de pelos envolto por um pano)", "duration": "Concentração, até 10 minutos", "description": ["Você estabelece um elo telepático com uma besta que você tocar que seja amigável a você ou que esteja enfeitiçada por você. A magia falha se o valor de Inteligência da besta for 4 ou maior.", "Até a magia acabar, o elo permanece ativo contanto que você e a besta tenham linha de visão um do outro.", "Através do elo, a besta pode compreender suas mensagens telepáticas e pode comunicar telepaticamente emoções e conceitos simples de volta para você.", "Enquanto o elo estiver ativo, a besta ganha vantagem nas jogadas de ataque contra qualquer criatura a até 1,5 metro de você que você possa ver."]}, "Bom Fruto": {"school": "1º nível de Transmutação", "time": "1 ação", "range": "Toque", "components": "V, G, M (um ramo de visco)", "duration": "Instantânea", "description": ["Até 10 frutos surgem na sua mão e são imbuídos com magia.", "Uma criatura pode usar sua ação para comer um fruto. Comer um fruto restaura 1 ponto de vida, e o fruto provê nutrição suficiente para manter uma criatura por um dia.", "Os frutos perdem sua potencialidade se não forem consumidos em até 24 horas após a conjuração da magia."]}, "Constrição": {"school": "1º nível de Conjuração", "time": "1 ação", "range": "27 metros", "components": "V, G", "duration": "Concentração, até 1 minuto", "description": ["Ervas daninhas e vinhas emaranhadas brotam do chão em um quadrado de 6 metros, a partir de um ponto dentro do alcance. Pela duração da magia, essas plantas tornam o chão terreno acidentado.", "Uma criatura na área quando a magia for lançada deve ter sucesso em um Teste de Resistência de Força ou ficará impedida pelas plantas emaranhadas até o término da magia.", "Uma criatura impedida pelas plantas pode usar sua ação para fazer um teste de Força contra sua CD de resistência à magia. Se tiver sucesso, ela se liberta.", "Quando a magia termina, as plantas conjuradas murcham e somem."]}, "Criar ou Destruir Água": {"school": "1º nível de Transmutação", "time": "1 ação", "range": "9 metros", "components": "V, G, M (uma gota de água, se estiver criando água, ou pequenos grãos de areia, se estiver destruindo)", "duration": "Instantânea", "description": ["Você cria ou destrói água.", "Criar Água. Você cria até 38 litros de água límpida e potável dentro do alcance em um recipiente aberto. Alternativamente, a água pode cair como chuva em um espaço equivalente a um cubo de 9 metros dentro do alcance, extinguindo chamas expostas na área.", "Destruir Água. Você destrói até 38 litros de água em um recipiente dentro do alcance. Alternativamente, pode destruir névoa em um espaço equivalente a um cubo de 9 metros dentro do alcance."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, pode criar ou destruir 38 litros adicionais, ou expandir o tamanho do cubo em 1,5 metro para cada nível acima do 1º."}, "Curar Ferimentos": {"school": "1º nível de Evocação", "time": "1 ação", "range": "Toque", "components": "V, G", "duration": "Instantânea", "description": ["Uma criatura que você tocar recupera uma quantidade de pontos de vida igual a: 1d8 + seu modificador de habilidade de conjuração.", "Esta magia não surte efeito em mortos-vivos ou construtos."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, a cura aumenta em 1d8 para cada nível acima do 1º."}, "Detectar Magia": {"school": "1º nível de Adivinhação (Ritual)", "time": "1 ação", "range": "Pessoal", "components": "V, G", "duration": "Concentração, até 10 minutos", "description": ["Durante a duração da magia, você sente a presença de magia a até 9 metros de você.", "Se detectar magia dentro dessa área, pode usar sua ação para enxergar uma aura branda em torno de qualquer criatura ou objeto visível que possua magia. Você também descobre a escola da magia, caso ela possua uma.", "A magia pode transpor a maioria das barreiras, mas é bloqueada por: 30 cm de pedra; 2,5 cm de metal comum; uma fina película de chumbo; 90 cm de barro ou sujeira."]}, "Detectar Veneno e Doença": {"school": "1º nível de Adivinhação (Ritual)", "time": "1 ação", "range": "Pessoal", "components": "V, G, M (uma folha de teixo)", "duration": "Concentração, até 10 minutos", "description": ["Pela duração da magia, você sente a presença e a localização de venenos, criaturas venenosas e doenças a até 9 metros de você.", "Você também identifica o tipo de veneno, criatura venenosa ou doença detectada.", "A magia pode penetrar a maioria das barreiras, mas é bloqueada por: 30 cm de pedra; 2,5 cm de metal comum; uma fina película de chumbo; 90 cm de madeira ou sujeira."]}, "Enfeitiçar Animal": {"school": "1º nível de Encantamento", "time": "1 ação", "range": "9 metros", "components": "V, G, M (uma porção de comida)", "duration": "24 horas", "description": ["Esta magia permite que você convença uma besta de que não oferece perigo.", "Escolha uma besta que possa ver dentro do alcance da magia. Ela deve ser capaz de ver e ouvir você.", "Se a besta tiver Inteligência 4 ou maior, a magia falha automaticamente. Caso contrário, ela deve ter sucesso em um Teste de Resistência de Sabedoria ou ficará enfeitiçada enquanto a magia durar.", "Se você ou um de seus companheiros ferir a besta, a magia termina."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, pode afetar uma besta adicional para cada nível acima do 1º."}, "Enfeitiçar Pessoa": {"school": "1º nível de Encantamento", "time": "1 ação", "range": "9 metros", "components": "V, G", "duration": "1 hora", "description": ["Você tenta enfeitiçar um humanoide que possa ver dentro do alcance da magia.", "O alvo deve realizar um Teste de Resistência de Sabedoria, feito com vantagem se você ou seus companheiros estiverem lutando contra ele.", "Caso fracasse, ficará enfeitiçado por você até a magia terminar ou até você ou seus companheiros fazerem algo nocivo contra ele.", "A criatura enfeitiçada considera você um conhecido amigável.", "Quando a magia termina, a criatura sabe que foi enfeitiçada por você."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, pode afetar um alvo adicional para cada nível acima do 1º. As criaturas escolhidas devem estar a menos de 9 metros umas das outras."}, "Falar com Animais": {"school": "1º nível de Adivinhação (Ritual)", "time": "1 ação", "range": "Pessoal", "components": "V, G", "duration": "10 minutos", "description": ["Você ganha a habilidade de compreender e se comunicar verbalmente com bestas enquanto durar a magia.", "O conhecimento e a consciência de muitas bestas são limitados pela sua Inteligência, mas, no mínimo, elas podem fornecer informações sobre localizações e monstros próximos, incluindo qualquer coisa que possam perceber ou tenham percebido no dia anterior.", "Você também pode tentar persuadir uma besta a realizar um pequeno favor, de acordo com a decisão do Mestre."]}, "Fogo das Fadas": {"school": "1º nível de Evocação", "time": "1 ação", "range": "18 metros", "components": "V", "duration": "Concentração, até 1 minuto", "description": ["Cada objeto em um cubo de 6 metros dentro do alcance fica contornado por uma luz azul, verde ou violeta, à sua escolha.", "Qualquer criatura na área também recebe o contorno caso falhe em um Teste de Resistência de Destreza.", "Enquanto durar a magia, objetos e criaturas afetados emanam penumbra em um raio de 3 metros.", "Qualquer jogada de ataque contra uma criatura ou objeto afetado possui vantagem, desde que o atacante possa vê-lo. Além disso, a criatura ou objeto afetado não pode se beneficiar de invisibilidade."]}, "Névoa": {"school": "1º nível de Conjuração", "time": "1 ação", "range": "36 metros", "components": "V, G", "duration": "Concentração, até 1 hora", "description": ["Você cria uma esfera de névoa com 6 metros de raio, centrada em um ponto dentro do alcance.", "A esfera se espalha ao redor de quinas e sua área é considerada ocultamento total.", "Ela permanece até o término da magia ou até que um vento de velocidade moderada ou maior a disperse, sendo necessário um vento de pelo menos 16 km/h."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, o raio da névoa aumenta em 6 metros para cada nível acima do 1º."}, "Onda Trovejante": {"school": "1º nível de Evocação", "time": "1 ação", "range": "Pessoal (cubo de 4,5 metros)", "components": "V", "duration": "Instantânea", "description": ["Uma onda de força trovejante irrompe de você.", "Cada criatura em um cubo de 4,5 metros originado em você deve realizar um Teste de Resistência de Constituição.", "Em uma falha, a criatura sofre 2d8 de dano trovejante e é empurrada 3 metros para longe de você.", "Em um sucesso, a criatura sofre metade do dano e não é empurrada.", "Além disso, objetos que não estejam sendo vestidos ou carregados e que estejam completamente dentro da área são automaticamente empurrados 3 metros para longe de você.", "A magia emite um estrondo trovejante audível a até 90 metros."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, o dano aumenta em 1d8 para cada nível acima do 1º."}, "Palavra de Cura": {"school": "1º nível de Evocação", "time": "1 ação bônus", "range": "18 metros", "components": "V", "duration": "Instantânea", "description": ["Uma criatura à sua escolha que você possa ver dentro do alcance recupera pontos de vida equivalentes a: 1d4 + seu modificador de habilidade de conjuração.", "Esta magia não possui efeito sobre construtos ou mortos-vivos."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, a cura aumenta em 1d4 para cada nível acima do 1º."}, "Passos Longos": {"school": "1º nível de Transmutação", "time": "1 ação", "range": "Toque", "components": "V, G, M (uma pitada de areia)", "duration": "1 hora", "description": ["Você toca uma criatura. O deslocamento do alvo aumenta em 3 metros até o término da magia."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, pode afetar uma criatura adicional para cada nível acima do 1º."}, "Purificar Comida e Bebida": {"school": "1º nível de Transmutação (Ritual)", "time": "1 ação", "range": "3 metros", "components": "V, G", "duration": "Instantânea", "description": ["Toda comida e bebida não mágica dentro de uma esfera de 1,5 metro de raio, centrada em um ponto à sua escolha dentro do alcance, é purificada e fica livre de venenos e doenças."]}, "Salto": {"school": "1º nível de Transmutação", "time": "1 ação", "range": "Toque", "components": "V, G, M (uma perna traseira de um gafanhoto)", "duration": "1 minuto", "description": ["Você toca uma criatura.", "Até o término da magia, a distância de salto da criatura é triplicada."]}, "Mãos Flamejantes": {"school": "1º nível de Evocação", "time": "1 ação", "range": "Pessoal (cone de 4,5 metros)", "components": "V, G", "duration": "Instantânea", "description": ["À medida que você mantém as mãos com os polegares se tocando e os dedos estendidos, um fino lençol de chamas é projetado da ponta dos seus dedos.", "Cada criatura em um cone de 4,5 metros deve realizar um Teste de Resistência de Destreza.", "Em uma falha, a criatura sofre 3d6 de dano de fogo. Em um sucesso, sofre metade do dano.", "O fogo incendeia qualquer objeto inflamável na área que não esteja sendo vestido ou carregado."], "higher": "Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, o dano aumenta em 1d6 para cada nível acima do 1º."}, "Agarrão da Terra": {"school": "2º nível de Transmutação", "time": "1 ação", "range": "90 metros", "components": "V", "duration": "Concentração, até 1 minuto", "description": ["Escolha uma criatura que você possa ver dentro do alcance. Laços amarelados de energia mágica rodeiam a criatura.", "O alvo deve ser bem-sucedido em um Teste de Resistência de Força ou seu deslocamento de voo, caso possua, será reduzido a 0 metros pela duração da magia.", "Uma criatura voadora afetada pela magia desce 18 metros por turno até aterrissar no solo ou a magia acabar."]}, "Diabo da Poeira": {"school": "2º nível de Conjuração", "time": "1 ação", "range": "18 metros", "components": "V, S, M (um punhado de pó)", "duration": "Concentração, até 1 minuto", "description": ["Escolha um cubo de ar desocupado de 1,5 metro que você possa ver dentro do alcance. Uma força elemental semelhante a um diabo da poeira aparece no cubo e permanece pela duração da magia.", "Qualquer criatura que terminar seu turno a até 1,5 metro do diabo da poeira deve realizar um Teste de Resistência de Força.", "Em uma falha, a criatura sofre 1d8 de dano de concussão e é empurrada 3 metros para longe. Em um sucesso, sofre metade do dano e não é empurrada.", "Como uma ação bônus, você pode mover o diabo da poeira em até 9 metros em qualquer direção.", "Se o diabo da poeira se mover sobre areia, poeira, terra solta ou cascalho, ele suga o material e forma uma nuvem de detritos com 3 metros de raio ao seu redor, que dura até o início do seu próximo turno. A área da nuvem fica densamente obscurecida."], "higher": "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d8 para cada nível acima do 2º."}, "Escrita Celeste": {"school": "2º nível de Transmutação (Ritual)", "time": "1 ação", "range": "Linha de visão", "components": "V, S", "duration": "Concentração, até 1 hora", "description": ["Você faz com que até dez palavras se formem em uma parte do céu que você possa ver.", "As palavras parecem ser feitas de nuvens e permanecem no local pela duração da magia.", "As palavras desaparecem quando a magia termina. Um vento forte pode dispersar as nuvens e terminar a magia prematuramente."]}, "Vento Protetor": {"school": "2º nível de Evocação", "time": "1 ação", "range": "Pessoal", "components": "V", "duration": "Concentração, até 10 minutos", "description": ["Um vento forte de aproximadamente 30 km/h sopra à sua volta em um raio de 3 metros e se move com você, permanecendo centrado em você.", "O vento possui os seguintes efeitos: ensurdece você e outras criaturas na área; extingue chamas desprotegidas na área que tenham o tamanho de tochas ou menores; a área é considerada terreno difícil para criaturas diferentes de você; jogadas de ataque à distância com armas têm desvantagem se passarem para dentro ou para fora do vento; afasta vapor, gás e névoa que possam ser dissipados por um vento forte."]}, "Crescer Espinhos": {"school": "2º nível de Transmutação", "time": "1 ação", "range": "45 metros", "components": "V, G, M (sete espinhos afiados ou sete pequenos galhos, cada um afiado em uma ponta)", "duration": "Concentração, até 10 minutos", "description": ["O chão em um raio de 6 metros, centrado em um ponto dentro do alcance, se contorce e dele brotam espinhos e cravos duros.", "A área se torna terreno acidentado pela duração da magia.", "Quando uma criatura se move para dentro ou através da área, ela sofre 2d4 de dano perfurante para cada 1,5 metro percorrido.", "A transformação do chão é camuflada de modo que pareça natural. Qualquer criatura que não possa ver a área no momento em que a magia for lançada deve realizar um teste de Sabedoria (Percepção) contra sua CD de resistência à magia para reconhecer o terreno como perigoso antes de entrar nele."]}, "Encontrar Armadilhas": {"school": "2º nível de Adivinhação", "time": "1 ação", "range": "36 metros", "components": "V, G", "duration": "Instantânea", "description": ["Você sente a presença de qualquer armadilha dentro do alcance que esteja em sua linha de visão.", "Para os propósitos desta magia, uma armadilha é algo criado especificamente para infligir um efeito súbito ou inesperado que você considere nocivo ou indesejável.", "Assim, a magia pode detectar uma área afetada por Alarme, Símbolo de Proteção ou uma armadilha mecânica, mas não pode revelar uma falha natural no piso, um teto instável ou um buraco escondido.", "A magia revela apenas que uma armadilha está presente. Você não descobre a localização de cada armadilha, mas pode descobrir a natureza geral do perigo imposto pela armadilha detectada."]}, "Esfera Flamejante": {"school": "2º nível de Conjuração", "time": "1 ação", "range": "18 metros", "components": "V, G, M (um pouco de sebo, um pedaço de enxofre e uma pitada de ferro em pó)", "duration": "Concentração, até 1 minuto", "description": ["Uma esfera de fogo de 1,5 metro de diâmetro surge em um espaço desocupado à sua escolha dentro do alcance e permanece até o fim da magia.", "Qualquer criatura que terminar seu turno a até 1,5 metro da esfera deve realizar um Teste de Resistência de Destreza.", "Em uma falha, a criatura sofre 2d6 de dano de fogo. Em um sucesso, sofre metade do dano.", "Como uma ação bônus, você pode mover a esfera em até 9 metros. Se lançá-la contra uma criatura, ela deve realizar o teste de resistência contra o dano da esfera, e a esfera para de se mover naquele turno.", "Ao mover a esfera, você pode fazê-la ultrapassar barreiras de até 1,5 metro de altura e saltar através de fossos de até 3 metros de largura.", "A esfera incendeia objetos inflamáveis que não estejam sendo vestidos ou carregados. Ela emana luz plena em um raio de 6 metros e penumbra por mais 6 metros."], "higher": "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d6 para cada nível acima do 2º."}, "Esquentar Metais": {"school": "2º nível de Transmutação", "time": "1 ação", "range": "18 metros", "components": "V, G, M (um pedaço de ferro e uma chama)", "duration": "Concentração, até 1 minuto", "description": ["Você escolhe um objeto de metal manufaturado, como uma arma de metal ou uma veste de armadura de metal média ou pesada, que possa ver dentro do alcance.", "Você faz com que o objeto se incandesça até ficar fortemente avermelhado pelo calor. Qualquer criatura em contato físico com o objeto sofre 2d8 de dano de fogo quando você conjura esta magia.", "Até o término da magia, você pode usar uma ação bônus em cada um dos seus turnos subsequentes para causar esse dano novamente.", "Se uma criatura estiver segurando ou vestindo o objeto e sofrer o dano, ela deve ser bem-sucedida em um Teste de Resistência de Constituição ou soltará o objeto, caso seja possível.", "Se não puder ou não soltar o objeto, ela terá desvantagem nas jogadas de ataque e testes de atributo até o início do seu próximo turno."], "higher": "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d8 para cada nível acima do 2º."}, "Habilidade Melhorada": {"school": "2º nível de Transmutação", "time": "1 ação", "range": "Toque", "components": "V, G, M (a pele ou a pena de uma besta)", "duration": "Concentração, até 1 hora", "description": ["Você toca uma criatura e concede a ela um aumento mágico. Escolha um dos seguintes efeitos, que permanece até o término da magia:", "Vigor do Urso. O alvo ganha vantagem nos testes de Constituição. Ele também recebe 2d6 pontos de vida temporários, que são perdidos quando a magia termina.", "Força do Touro. O alvo ganha vantagem nos testes de Força e tem sua capacidade de carga duplicada.", "Agilidade Felina. O alvo ganha vantagem nos testes de Destreza. Além disso, não sofre dano ao cair de uma altura de 6 metros ou menos, desde que não esteja incapacitado.", "Esplendor da Águia. O alvo ganha vantagem nos testes de Carisma.", "Astúcia da Raposa. O alvo ganha vantagem nos testes de Inteligência.", "Sabedoria da Coruja. O alvo ganha vantagem nos testes de Sabedoria."], "higher": "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, pode afetar uma criatura adicional para cada nível acima do 2º."}, "Imobilizar Pessoa": {"school": "2º nível de Encantamento", "time": "1 ação", "range": "18 metros", "components": "V, G, M (uma pequena peça reta de ferro)", "duration": "Concentração, até 1 minuto", "description": ["Escolha um humanoide que você possa ver dentro do alcance.", "O alvo deve ser bem-sucedido em um Teste de Resistência de Sabedoria ou ficará paralisado pela duração da magia.", "No final de cada um dos turnos do alvo, ele pode realizar outro Teste de Resistência de Sabedoria. Em um sucesso, o efeito da magia termina sobre ele."], "higher": "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, pode afetar um humanoide adicional para cada nível acima do 2º. Os humanoides devem estar a até 9 metros uns dos outros quando você os escolher como alvos."}, "Lâmina Flamejante": {"school": "2º nível de Evocação", "time": "1 ação bônus", "range": "Pessoal", "components": "V, G, M (uma folha de sumac)", "duration": "Concentração, até 10 minutos", "description": ["Você evoca uma lâmina flamejante em sua mão livre. A lâmina é similar em tamanho e formato a uma cimitarra e permanece pela duração da magia.", "Se você soltar a lâmina, ela desaparece, mas pode evocá-la novamente usando uma ação bônus.", "Você pode usar sua ação para realizar um ataque mágico corpo a corpo com a lâmina flamejante. Se acertar, o alvo sofre 3d6 de dano de fogo.", "A lâmina emana luz intensa em um raio de 3 metros e penumbra por mais 3 metros."], "higher": "Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, o dano aumenta em 1d6 para cada dois níveis acima do 2º."}, "Localizar Animais ou Plantas": {"school": "2º nível de Adivinhação (Ritual)", "time": "1 ação", "range": "Pessoal", "components": "V, G, M (um pedaço de pele de um cão de caça)", "duration": "Instantânea", "description": ["Você descreve ou nomeia um tipo específico de besta ou planta.", "Concentrando-se na voz da natureza ao seu redor, você descobre a direção e a distância até a criatura ou planta mais próxima daquela espécie dentro de 8 km, caso esteja presente."]}, "Localizar Objeto": {"school": "2º nível de Adivinhação", "time": "1 ação", "range": "Pessoal", "components": "V, G, M (um galho bifurcado)", "duration": "Concentração, até 10 minutos", "description": ["Você descreve ou cita o nome de um objeto que seja familiar a você.", "Você sente a direção da localização do objeto, desde que ele esteja a até 300 metros de você. Se o objeto estiver em movimento, você também sabe a direção desse movimento.", "A magia pode localizar um objeto específico conhecido por você, desde que tenha visto o objeto de perto — a pelo menos 9 metros — ao menos uma vez.", "Alternativamente, a magia pode localizar o objeto mais próximo de um determinado tipo, como um certo modelo de aparelho, joia, mobília, ferramenta ou arma.", "Esta magia não pode localizar um objeto se qualquer espessura de chumbo, mesmo uma folha fina, estiver bloqueando um caminho direto entre você e o objeto."]}, "Lufada de Vento": {"school": "2º nível de Evocação", "time": "1 ação", "range": "Pessoal (linha de 18 metros)", "components": "V, G, M (uma semente de uma leguminosa)", "duration": "Concentração, até 10 minutos", "description": ["Uma linha de vento forte com 18 metros de comprimento e 3 metros de largura irrompe de você em uma direção à sua escolha enquanto a magia durar.", "Cada criatura que começar seu turno na linha deve ser bem-sucedida em um Teste de Resistência de Força ou será empurrada 4,5 metros para longe de você, seguindo a direção da linha.", "Qualquer criatura na linha deve gastar 3 metros de deslocamento para cada 1,5 metro percorrido ao se mover em sua direção.", "A rajada dispersa gás e vapor e extingue velas, tochas e outras chamas desprotegidas similares na área. Chamas protegidas, como as de lanternas, movem-se descontroladamente e possuem 50% de chance de serem apagadas.", "Como uma ação bônus em cada um dos seus turnos, você pode mudar a direção em que a linha irrompe de você."]}, "Mensageiro Animal": {"school": "2º nível de Encantamento (Ritual)", "time": "1 ação", "range": "9 metros", "components": "V, G, M (uma porção de comida)", "duration": "24 horas", "description": ["Através desta magia, você utiliza um animal para entregar uma mensagem.", "Escolha uma besta Miúda que possa ver dentro do alcance, como um esquilo, uma gralha-azul ou um morcego.", "Você especifica uma localização que já tenha visitado e um destinatário que possa ser descrito de maneira geral, como \"um homem ou uma mulher vestindo o uniforme da guarda da cidade\" ou \"um anão ruivo usando um chapéu pontudo\".", "Você pode enviar uma mensagem de até 25 palavras.", "A besta viaja até o local especificado enquanto durar a magia, percorrendo até 80 km a cada 24 horas, caso seja um mensageiro voador; ou 40 km a cada 24 horas, para outros animais.", "Quando chega ao destino, o mensageiro entrega a mensagem à criatura descrita, replicando o som da sua voz. Ele fala apenas com uma criatura que corresponda à descrição fornecida.", "Se o mensageiro não alcançar seu destino antes do término da magia, a mensagem é perdida e a besta retorna ao local onde a magia foi conjurada."], "higher": "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, a duração aumenta em 48 horas para cada nível acima do 2º."}, "Passo sem Pegadas": {"school": "2º nível de Abjuração", "time": "1 ação", "range": "Pessoal", "components": "V, G, M (cinzas de uma folha queimada de visco e um ramo de abeto)", "duration": "Concentração, até 1 hora", "description": ["Um véu de sombras e silêncio irradia de você, mascarando você e seus companheiros contra detecção.", "Pela duração da magia, cada criatura que você escolher a até 9 metros de você, incluindo você mesmo, recebe +10 de bônus nos testes de Destreza (Furtividade).", "As criaturas afetadas não podem ser rastreadas, exceto por meios mágicos.", "Uma criatura que recebe esse bônus não deixa pegadas ou outros vestígios de sua passagem."]}, "Pele de Árvore": {"school": "2º nível de Transmutação", "time": "1 ação", "range": "Toque", "components": "V, G, M (um punhado de casca de carvalho)", "duration": "Concentração, até 1 hora", "description": ["Você toca uma criatura voluntária.", "Até o término da magia, a pele do alvo fica áspera e assume a aparência de uma casca de árvore.", "A CA do alvo não pode ser menor que 16, independentemente do tipo de armadura que esteja vestindo."]}, "Proteção contra Venenos": {"school": "2º nível de Abjuração", "time": "1 ação", "range": "Toque", "components": "V, G", "duration": "1 hora", "description": ["Você toca uma criatura. Se ela estiver envenenada, você neutraliza o veneno.", "Se mais de um veneno estiver afetando o alvo, você neutraliza um veneno que saiba estar presente ou neutraliza um deles aleatoriamente.", "Enquanto a magia durar, o alvo recebe vantagem nos Testes de Resistência contra ser envenenado e resistência a dano de veneno."]}, "Raio Ardente": {"school": "2º nível de Evocação", "time": "1 ação", "range": "36 metros", "components": "V, G", "duration": "Instantânea", "description": ["Você cria três raios de fogo e os arremessa contra alvos dentro do alcance.", "Você pode direcionar os raios contra um único alvo ou vários alvos.", "Faça uma jogada de ataque mágico à distância para cada raio. Em um acerto, o alvo sofre 2d6 de dano de fogo."], "higher": "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, cria um raio adicional para cada nível acima do 2º."}, "Raio Lunar": {"school": "2º nível de Evocação", "time": "1 ação", "range": "36 metros", "components": "V, G, M (um punhado de sementes-da-lua e um pedaço de feldspato)", "duration": "Concentração, até 1 minuto", "description": ["Um feixe prateado de luz pálida forma um cilindro de 1,5 metro de raio e 12 metros de altura, centrado em um ponto dentro do alcance. Até o término da magia, uma penumbra preenche o cilindro.", "Quando uma criatura entra na área da magia pela primeira vez em um turno ou começa seu turno dentro dela, ela é envolvida por chamas fantasmagóricas que causam dores lancinantes e deve realizar um Teste de Resistência de Constituição.", "Em uma falha, a criatura sofre 2d10 de dano radiante. Em um sucesso, sofre metade do dano.", "Um metamorfo realiza o teste de resistência com desvantagem. Se falhar, ele automaticamente retorna à sua forma normal e não pode assumir uma forma diferente até sair da iluminação da magia.", "Em cada um dos seus turnos após conjurar a magia, você pode usar uma ação para mover o feixe em até 18 metros em qualquer direção."], "higher": "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d10 para cada nível acima do 2º."}, "Restauração Menor": {"school": "2º nível de Abjuração", "time": "1 ação", "range": "Toque", "components": "V, G", "duration": "Instantânea", "description": ["Você toca uma criatura e pode encerrar uma doença ou uma condição que a esteja afligindo.", "A condição pode ser: Cegueira, Surdez, Paralisia ou Envenenamento."]}, "Sentidos da Besta": {"school": "2º nível de Adivinhação (Ritual)", "time": "1 ação", "range": "Toque", "components": "G", "duration": "Concentração, até 1 hora", "description": ["Você toca uma besta voluntária.", "Enquanto a magia durar, você pode usar sua ação para ver através dos olhos da besta e ouvir o que ela ouve. Esse efeito permanece até você usar sua ação para retornar aos seus sentidos normais.", "Enquanto estiver percebendo através dos sentidos da besta, você recebe quaisquer sentidos especiais que ela possua.", "Durante esse período, você fica cego e surdo em relação aos seus próprios arredores."]}, "Visão no Escuro": {"school": "2º nível de Transmutação", "time": "1 ação", "range": "Toque", "components": "V, G, M (um punhado de cenouras secas ou uma ágata)", "duration": "8 horas", "description": ["Você toca uma criatura voluntária para conceder a ela a habilidade de enxergar no escuro.", "Pela duração da magia, a criatura recebe visão no escuro com alcance de 18 metros."]}, "Erupção de Terra": {"school": "3º nível de Transmutação", "time": "1 ação", "range": "36 metros", "components": "V, S, M (um pedaço de obsidiana)", "duration": "Instantânea", "description": ["Escolha um ponto que você possa ver no solo, dentro do alcance. Uma fonte de terra e pedras se agita e emerge em um cubo de 6 metros, centrado no ponto.", "Cada criatura na área deve realizar um Teste de Resistência de Destreza.", "Em uma falha, a criatura sofre 3d12 de dano de concussão. Em um sucesso, sofre metade do dano.", "Além disso, o solo na área se torna terreno difícil até ser limpo. Cada porção de 1,5 metro quadrado da área requer pelo menos 1 minuto para ser limpa manualmente."], "higher": "Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, o dano aumenta em 1d12 para cada nível acima do 3º."}, "Maremoto": {"school": "3º nível de Conjuração", "time": "1 ação", "range": "36 metros", "components": "V, S, M (uma gota de água)", "duration": "Instantânea", "description": ["Você conjura uma onda de água que se choca contra uma área dentro do alcance.", "A área pode ter até 9 metros de comprimento, 3 metros de largura e 3 metros de altura.", "Cada criatura na área deve realizar um Teste de Resistência de Destreza.", "Em uma falha, a criatura sofre 4d8 de dano de concussão e fica caída. Em um sucesso, sofre metade do dano e não é derrubada.", "A água então se espalha pelo solo em todas as direções, extinguindo chamas desprotegidas em sua área e a até 9 metros dela."]}, "Muralha de Água": {"school": "3º nível de Evocação", "time": "1 ação", "range": "18 metros", "components": "V, S, M (uma gota de água)", "duration": "Concentração, até 10 minutos", "description": ["Você conjura uma muralha de água no solo, em um ponto que possa ver dentro do alcance.", "Você pode criar a muralha com até 9 metros de largura, 3 metros de altura e 30 centímetros de espessura, ou criar uma muralha em forma de anel com 6 metros de diâmetro, 6 metros de altura e 30 centímetros de espessura.", "A muralha desaparece quando a magia termina. O espaço ocupado pela muralha é considerado terreno difícil.", "Qualquer ataque à distância com arma que entre no espaço da muralha tem desvantagem na jogada de ataque.", "O dano de fogo é reduzido à metade se o efeito de fogo passar através da muralha para alcançar seu alvo.", "Magias que causem dano de frio e passem através da muralha fazem com que a área atravessada congele, com pelo menos uma seção de 1,5 metro sendo congelada.", "Cada seção congelada de 1,5 metro possui CA 5 e 15 pontos de vida. Reduzir uma seção a 0 pontos de vida a destrói. Quando uma seção congelada é destruída, a água não volta a preencher aquele espaço."]}, "Ampliar Plantas": {"school": "3º nível de Transmutação", "time": "1 ação ou 8 horas", "range": "45 metros", "components": "V, G", "duration": "Instantânea", "description": ["Esta magia canaliza vitalidade para as plantas de uma área específica. Existem dois usos possíveis, proporcionando um benefício imediato ou de longo prazo.", "1 ação. Escolha um ponto dentro do alcance. Todas as plantas normais dentro de um raio de 30 metros, centrado nesse ponto, tornam-se espessas e maiores.", "Uma criatura que se mova através da área deve gastar 6 metros de deslocamento para cada 1,5 metro percorrido.", "Você pode excluir uma ou mais áreas de qualquer tamanho dentro da área da magia para que não sejam afetadas.", "8 horas. Você enriquece a terra. Todas as plantas em um raio de 800 metros, centrado em um ponto dentro do alcance, ficam enriquecidas por 1 ano.", "As plantas produzem o dobro da quantidade normal de alimento quando colhidas."]}, "Caminhar na Água": {"school": "3º nível de Transmutação (Ritual)", "time": "1 ação", "range": "9 metros", "components": "V, G, M (um pedaço de rolha)", "duration": "1 hora", "description": ["Esta magia concede a habilidade de se mover sobre superfícies líquidas — como água, ácido, lama, neve, areia movediça ou lava — como se fossem superfícies sólidas e inofensivas.", "Uma criatura que atravesse lava derretida ainda pode sofrer dano devido ao calor.", "Até 10 criaturas voluntárias que você possa ver dentro do alcance recebem essa habilidade pela duração da magia.", "Se você escolher como alvo uma criatura submersa em um líquido, a magia faz com que ela suba em direção à superfície a uma velocidade de 18 metros por rodada."]}, "Convocar Relâmpagos": {"school": "3º nível de Conjuração", "time": "1 ação", "range": "36 metros", "components": "V, G", "duration": "Concentração, até 10 minutos", "description": ["Uma nuvem de tempestade surge na forma de um cilindro de 3 metros de altura e 18 metros de raio, centrado em um ponto que você possa ver 30 metros diretamente acima de você.", "A magia falha se você não puder ver um ponto no ar onde a nuvem possa aparecer, como em um ambiente fechado que não possa acomodá-la.", "Quando você conjura a magia, escolha um ponto que possa ver dentro do alcance. Um relâmpago cai da nuvem nesse ponto.", "Cada criatura a até 1,5 metro do ponto deve realizar um Teste de Resistência de Destreza.", "Em uma falha, a criatura sofre 3d10 de dano elétrico. Em um sucesso, sofre metade do dano.", "Em cada um dos seus turnos, até o término da magia, você pode usar sua ação para convocar outro relâmpago, escolhendo o mesmo ponto ou outro diferente.", "Se você estiver em uma área externa que já esteja sob condições de uma tempestade quando conjurar esta magia, você assume o controle da tempestade existente em vez de criar uma nova. Nessas condições, o dano da magia aumenta em 1d10."], "higher": "Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, o dano aumenta em 1d10 para cada nível acima do 3º."}, "Dissipar Magia": {"school": "3º nível de Abjuração", "time": "1 ação", "range": "36 metros", "components": "V, G", "duration": "Instantânea", "description": ["Escolha uma criatura, objeto ou efeito mágico dentro do alcance.", "Qualquer magia de 3º nível ou inferior sobre o alvo é dissipada.", "Para cada magia de 4º nível ou superior sobre o alvo, faça um teste de atributo usando sua habilidade de conjuração. A CD é igual a 10 + o nível da magia. Em um sucesso, a magia é dissipada."], "higher": "Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, encerra automaticamente os efeitos de uma magia sobre o alvo cujo nível seja igual ou inferior ao nível do espaço de magia utilizado."}, "Falar com Plantas": {"school": "3º nível de Transmutação", "time": "1 ação", "range": "Pessoal (raio de 9 metros)", "components": "V, G", "duration": "10 minutos", "description": ["Você imbui as plantas a até 9 metros de você com senciência e animação limitadas, dando a elas a capacidade de se comunicar com você e seguir comandos simples.", "Você pode perguntar às plantas sobre eventos ocorridos no último dia dentro da área da magia, recebendo informações sobre criaturas que passaram pelo local, o clima e outras circunstâncias.", "Você também pode transformar terreno acidentado causado por plantas, como moitas e vegetação rasteira, em terreno normal pela duração da magia.", "Da mesma forma, pode transformar terreno normal onde existam plantas em terreno acidentado, fazendo com que vinhas e galhos atrasem perseguidores, por exemplo.", "As plantas podem ser capazes de realizar outras tarefas em seu favor, de acordo com a decisão do Mestre. A magia não permite que elas se desenraízem e se movam, mas elas podem movimentar livremente galhos, gavinhas e caules.", "Se uma criatura do tipo planta estiver na área, você pode se comunicar com ela como se compartilhassem o mesmo idioma, mas não recebe nenhuma habilidade mágica para influenciá-la.", "Esta magia também pode fazer com que plantas criadas pela magia Constrição libertem uma criatura impedida."]}, "Fingir-se de Morto": {"school": "3º nível de Necromancia (Ritual)", "time": "1 ação", "range": "Toque", "components": "V, G, M (uma pitada de areia de cemitério)", "duration": "1 hora", "description": ["Você toca uma criatura voluntária e a coloca em um estado cataléptico indistinguível da morte.", "Enquanto a magia durar, ou até você usar uma ação para tocar o alvo e encerrar a magia, ele parece morto para todos os meios de inspeção e para magias utilizadas para determinar sua condição.", "O alvo fica cego e incapacitado, e seu deslocamento é reduzido a 0.", "Além disso, recebe resistência a todos os tipos de dano, exceto dano psíquico.", "Se o alvo estiver doente ou envenenado quando a magia for conjurada, ou ficar doente ou envenenado enquanto estiver sob seu efeito, a doença e o veneno não produzem efeitos até a magia terminar."]}, "Invocar Animais": {"school": "3º nível de Conjuração", "time": "1 ação", "range": "18 metros", "components": "V, G", "duration": "Concentração, até 1 hora", "description": ["Você invoca espíritos feéricos que assumem a forma de bestas e aparecem em espaços desocupados que possa ver dentro do alcance.", "Escolha uma das seguintes opções: Uma besta de ND 2 ou inferior; Duas bestas de ND 1 ou inferior; Quatro bestas de ND 1/2 ou inferior; Oito bestas de ND 1/4 ou inferior.", "Cada besta é considerada feérica e desaparece quando chega a 0 pontos de vida ou quando a magia termina.", "As criaturas invocadas são amigáveis a você e aos seus aliados. Role a iniciativa para as criaturas invocadas como um grupo, que possui seus próprios turnos.", "Elas obedecem a quaisquer comandos verbais que você der, sem exigir uma ação sua. Se você não emitir nenhum comando, elas se defendem de criaturas hostis, mas não realizam outras ações.", "O Mestre possui as estatísticas das criaturas."], "higher": "Ao utilizar espaços de magia superiores, a quantidade de criaturas invocadas aumenta: 5º nível: o dobro de criaturas. 7º nível: o triplo de criaturas. 9º nível: o quádruplo de criaturas."}, "Luz do Dia": {"school": "3º nível de Evocação", "time": "1 ação", "range": "18 metros", "components": "V, G", "duration": "1 hora", "description": ["Uma esfera de luz com 18 metros de raio emana de um ponto à sua escolha dentro do alcance.", "A esfera emana luz plena em sua área e penumbra por mais 18 metros.", "Se o ponto escolhido for um objeto que você esteja segurando ou um objeto que não esteja sendo vestido ou carregado, a luz emana desse objeto e se move com ele.", "Cobrir completamente a fonte da luz com um objeto opaco, como uma caixa ou elmo, bloqueia a luz.", "Se qualquer área desta magia se sobrepor a uma área de escuridão criada por uma magia de 3º nível ou inferior, a magia que criou a escuridão é dissipada."]}, "Mesclar-se às Rochas": {"school": "3º nível de Transmutação (Ritual)", "time": "1 ação", "range": "Toque", "components": "V, G", "duration": "8 horas", "description": ["Você entra em um objeto ou superfície de pedra grande o suficiente para comportar completamente seu corpo, fundindo-se com a pedra junto de todo o equipamento que estiver carregando.", "Usando seu movimento, você entra na pedra em um ponto que possa tocar. Nenhum sinal de sua presença permanece visível ou detectável por sentidos não mágicos.", "Enquanto estiver fundido à pedra, você não pode ver o que acontece fora dela. Qualquer teste de Sabedoria (Percepção) realizado para ouvir sons externos é feito com desvantagem.", "Você permanece consciente da passagem do tempo e pode conjurar magias sobre si mesmo enquanto estiver fundido.", "Você pode usar seu movimento para sair da pedra pelo local onde entrou, encerrando a magia. Caso contrário, não pode se mover.", "Pequenos danos físicos causados à pedra não ferem você. Porém, uma destruição parcial ou alteração suficiente para que a pedra não possa mais comportar seu corpo o expele e causa 6d6 de dano de concussão.", "A destruição completa da pedra, ou sua transmutação em outra substância, também o expele e causa 50 pontos de dano de concussão.", "Se for expelido, você fica caído no espaço desocupado mais próximo de onde entrou."]}, "Muralha de Vento": {"school": "3º nível de Evocação", "time": "1 ação", "range": "36 metros", "components": "V, G, M (um pequeno leque e uma pena de origem exótica)", "duration": "Concentração, até 1 minuto", "description": ["Uma parede de vento forte ergue-se do chão em um ponto à sua escolha dentro do alcance.", "A parede pode ter até 15 metros de comprimento, 4,5 metros de altura e 30 centímetros de espessura. Você pode moldá-la da maneira que desejar, desde que ela forme um caminho contínuo sobre o solo.", "Quando a parede surge, cada criatura em sua área deve realizar um Teste de Resistência de Força.", "Em uma falha, a criatura sofre 3d8 de dano de concussão. Em um sucesso, sofre metade do dano.", "A força do vento impede a passagem de névoa, fumaça e outros gases.", "Criaturas voadoras de tamanho Pequeno ou menor e objetos similares não conseguem atravessar a parede.", "Materiais leves e soltos levados até a parede são lançados para cima.", "Flechas, virotes e outros projéteis comuns disparados contra alvos do outro lado da parede são desviados para cima e erram automaticamente. Pedregulhos lançados por gigantes, projéteis de armas de cerco e similares não são afetados.", "Criaturas em forma gasosa não podem atravessar a parede."]}, "Nevasca": {"school": "3º nível de Conjuração", "time": "1 ação", "range": "45 metros", "components": "V, G, M (uma pitada de poeira e algumas gotas de água)", "duration": "Concentração, até 1 minuto", "description": ["Até o término da magia, uma chuva congelante e de granizo cai em um cilindro de 6 metros de altura e 12 metros de raio, centrado em um ponto à sua escolha dentro do alcance.", "A área possui ocultamento total, e qualquer chama exposta dentro dela é extinguida.", "O chão fica coberto por gelo escorregadio, tornando-se terreno acidentado.", "Quando uma criatura entra na área da magia pela primeira vez em seu turno ou começa seu turno dentro dela, deve realizar um Teste de Resistência de Destreza. Em uma falha, fica caída.", "Se uma criatura estiver mantendo concentração dentro da área da magia, deve ser bem-sucedida em um Teste de Resistência de Constituição contra sua CD de resistência à magia ou perderá a concentração."]}, "Proteção contra Energia": {"school": "3º nível de Abjuração", "time": "1 ação", "range": "Toque", "components": "V, G", "duration": "Concentração, até 1 hora", "description": ["Enquanto a magia durar, uma criatura voluntária que você tocar recebe resistência a um tipo de dano à sua escolha: Ácido, Frio, Fogo, Elétrico ou Trovejante."]}, "Respirar na Água": {"school": "3º nível de Transmutação (Ritual)", "time": "1 ação", "range": "9 metros", "components": "V, G, M (um pequeno pedaço de vara de bambu ou um pouco de palha)", "duration": "24 horas", "description": ["Esta magia concede a até 10 criaturas voluntárias que você possa ver dentro do alcance a habilidade de respirar debaixo d'água até o término da magia.", "As criaturas afetadas também mantêm sua forma normal de respiração."]}, "Reviver": {"school": "3º nível de Conjuração", "time": "1 ação", "range": "Toque", "components": "V, G, M (um diamante no valor de pelo menos 300 PO, consumido pela magia)", "duration": "Instantânea", "description": ["Você toca uma criatura que tenha morrido há no máximo 1 minuto.", "A criatura retorna à vida com 1 ponto de vida.", "Esta magia não pode trazer de volta à vida uma criatura que tenha morrido de velhice e não pode restaurar partes do corpo que estejam faltando."]}, "Destruição Elemental": {"school": "4º nível de Transmutação", "time": "1 ação", "range": "27 metros", "components": "V, S", "duration": "Concentração, até 1 minuto", "description": ["Escolha uma criatura que você possa ver dentro do alcance e escolha um dos seguintes tipos de dano: ácido, frio, fogo, elétrico ou trovejante.", "O alvo deve ser bem-sucedido em um Teste de Resistência de Constituição ou será afetado pela magia durante sua duração.", "Da primeira vez, a cada turno, que o alvo sofrer dano do tipo escolhido, ele sofre 2d6 de dano extra do mesmo tipo.", "Além disso, o alvo perde qualquer resistência ao tipo de dano escolhido até a magia terminar."], "higher": "Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, pode afetar uma criatura adicional para cada nível acima do 4º. As criaturas devem estar a até 9 metros umas das outras quando forem escolhidas."}, "Enfeitiçar Monstro": {"school": "4º nível de Encantamento", "time": "1 ação", "range": "9 metros", "components": "V, S", "duration": "1 hora", "description": ["Você tenta enfeitiçar uma criatura que possa ver dentro do alcance.", "Ela deve realizar um Teste de Resistência de Sabedoria, feito com vantagem se você ou seus companheiros estiverem lutando contra ela.", "Em uma falha, a criatura fica enfeitiçada por você até a magia terminar ou até que você ou seus companheiros façam algo prejudicial contra ela.", "A criatura enfeitiçada é amigável a você.", "Quando a magia termina, a criatura sabe que foi enfeitiçada por você."], "higher": "Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, pode afetar uma criatura adicional para cada nível acima do 4º. As criaturas devem estar a até 9 metros umas das outras quando forem escolhidas."}, "Esfera Aquosa": {"school": "4º nível de Conjuração", "time": "1 ação", "range": "27 metros", "components": "V, S, M (uma gotícula de água)", "duration": "Concentração, até 1 minuto", "description": ["Você conjura uma esfera de água com 3 metros de raio em um ponto que possa ver dentro do alcance.", "A esfera pode flutuar no ar, mas não pode ficar a mais de 3 metros do chão.", "Qualquer criatura no espaço da esfera deve realizar um Teste de Resistência de Força. Em um sucesso, a criatura é ejetada para o espaço desocupado mais próximo fora da esfera. Uma criatura Enorme ou maior obtém sucesso automaticamente.", "Em uma falha, a criatura fica impedida pela esfera e engolfada pela água. No final de cada um dos seus turnos, um alvo impedido pode repetir o teste de resistência.", "A esfera pode conter no máximo quatro criaturas Médias ou menores, ou uma criatura Grande. Se exceder essa capacidade, uma criatura aleatória que já esteja impedida é ejetada e fica caída em um espaço a até 1,5 metro da esfera.", "Com uma ação, você pode mover a esfera até 9 metros em linha reta. Se atravessar um fosso, penhasco ou outra queda, ela desce em segurança até ficar novamente a até 3 metros do chão.", "Qualquer criatura impedida pela esfera se move junto com ela. Você pode arremessar a esfera contra criaturas, forçando-as a realizar o teste de resistência, mas não mais de uma vez por turno.", "Quando a magia termina, a esfera cai no chão e extingue todas as chamas normais a até 9 metros dela. Qualquer criatura que estivesse impedida fica caída no espaço onde a esfera caiu."]}, "Guardião da Natureza": {"school": "4º nível de Transmutação", "time": "1 ação bônus", "range": "Pessoal", "components": "V", "duration": "Concentração, até 1 minuto", "description": ["Um espírito da natureza responde ao seu chamado e transforma você em um poderoso guardião. Escolha uma das seguintes formas: Fera Primitiva ou Grande Árvore.", "Fera Primitiva. Pele bestial cobre seu corpo, seus traços faciais tornam-se selvagens e você recebe os seguintes benefícios: seu deslocamento aumenta em 3 metros; recebe visão no escuro com alcance de 36 metros; seus ataques baseados em Força têm vantagem; seus ataques com armas corpo a corpo causam 1d6 de dano de energia adicional ao acertar.", "Grande Árvore. Sua pele assume a aparência de um tronco, folhas brotam de seu cabelo e você recebe os seguintes benefícios: recebe 10 pontos de vida temporários; realiza testes de Constituição com vantagem; seus ataques baseados em Destreza e Sabedoria têm vantagem; enquanto estiver no chão, a área a até 4,5 metros de você é terreno difícil para seus inimigos."]}, "Confusão": {"school": "4º nível de Encantamento", "time": "1 ação", "range": "27 metros", "components": "V, G, M (três cascas de nozes)", "duration": "Concentração, até 1 minuto", "description": ["Esta magia violenta e distorce a mente das criaturas, plantando ilusões e provocando ações incontroladas.", "Cada criatura em uma esfera de 3 metros de raio, centrada em um ponto à sua escolha dentro do alcance, deve realizar um Teste de Resistência de Sabedoria. Em uma falha, a criatura é afetada pela magia.", "Uma criatura afetada não pode realizar reações e deve rolar 1d10 no início de cada um de seus turnos para determinar seu comportamento: 1 — usa todo o movimento em uma direção aleatória (role 1d8) e não realiza ações; 2–6 — não se move nem realiza ações; 7–8 — usa sua ação para realizar um ataque corpo a corpo contra uma criatura aleatória ao seu alcance, ou não faz nada se não houver nenhuma; 9–10 — pode agir e se mover normalmente.", "No final de cada um de seus turnos, uma criatura afetada pode realizar outro Teste de Resistência de Sabedoria. Em um sucesso, o efeito termina para ela."], "higher": "Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, o raio da esfera aumenta em 1,5 metro para cada nível acima do 4º."}, "Controlar Água": {"school": "4º nível de Transmutação", "time": "1 ação", "range": "90 metros", "components": "V, G, M (uma gota de água e uma pitada de poeira)", "duration": "Concentração, até 10 minutos", "description": ["Até o término da magia, você controla qualquer água livre dentro de uma área à sua escolha equivalente a um cubo de 30 metros. Ao conjurar a magia, escolha um dos efeitos abaixo. Como uma ação em seus turnos, você pode repetir o mesmo efeito ou escolher um diferente.", "Inundação. Você aumenta o nível de toda a água parada na área em até 6 metros. Se a área possuir um litoral, a inundação transborda sobre a terra. Em um grande corpo de água, você pode criar uma onda de 6 metros de altura que atravessa a área. Veículos Enormes ou menores no caminho são levados até o outro lado e possuem 25% de chance de virar. O nível permanece elevado até a magia terminar ou você escolher outro efeito. Se produzir uma onda, ela se repete no início do seu próximo turno enquanto Inundação permanecer ativa.", "Dividir Águas. Você faz com que a água na área se separe, criando uma trincheira. A água separada forma uma parede de cada lado. A trincheira permanece até a magia terminar ou você escolher outro efeito; depois disso, a água preenche lentamente a trincheira durante a rodada seguinte.", "Definir Corrente. Você faz a água corrente se mover em uma direção à sua escolha, mesmo sobre obstáculos, paredes ou direções improváveis. Ao sair da área da magia, ela volta a seguir as condições naturais do terreno. O efeito dura até a magia terminar ou você escolher outro.", "Vórtice. Requer um corpo d'água de pelo menos 15 metros quadrados e 7,5 metros de profundidade. Você cria um vórtice com 1,5 metro de largura na base, até 15 metros no topo e 7,5 metros de altura. Objetos ou criaturas na água a até 7,5 metros são puxados 3 metros em sua direção. Uma criatura pode tentar nadar para fora com um teste de Força (Atletismo) contra sua CD de resistência à magia.", "Quando uma criatura entra no vórtice pela primeira vez em um turno ou começa seu turno nele, deve realizar um Teste de Resistência de Força. Em uma falha, sofre 2d8 de dano de concussão e fica presa até a magia terminar. Em um sucesso, sofre metade e não fica presa. Uma criatura presa pode usar sua ação para tentar nadar para fora, com desvantagem no teste. Na primeira vez em cada turno que um objeto entra no vórtice, sofre 2d8 de dano de concussão, repetido a cada rodada em que permanecer nele."]}, "Dominar Animais": {"school": "4º nível de Encantamento", "time": "1 ação", "range": "18 metros", "components": "V, G", "duration": "Concentração, até 1 minuto", "description": ["Você tenta dominar uma besta que possa ver dentro do alcance. Ela deve realizar um Teste de Resistência de Sabedoria ou ficará enfeitiçada pela duração da magia. Se você ou seus aliados estiverem lutando contra ela, realiza o teste com vantagem.", "Enquanto estiver enfeitiçada, você possui um elo telepático com ela enquanto ambos estiverem no mesmo plano de existência. Você pode usar esse elo para emitir comandos enquanto estiver consciente, sem precisar usar uma ação. Ela tentará obedecer da melhor maneira possível.", "Você pode especificar uma ação simples ou um curso geral de ações. Se a criatura completar a ordem e não receber novas instruções, passa a se defender e preservar da melhor maneira possível.", "Você pode usar sua ação para assumir controle preciso e total da criatura. Até o final do seu próximo turno, ela realiza apenas as ações que você escolher e não faz nada que você não permita. Durante esse período, você também pode fazê-la utilizar uma reação, mas isso exige sua própria reação.", "Sempre que o alvo sofrer dano, ele realiza um novo Teste de Resistência de Sabedoria. Em um sucesso, a magia termina."], "higher": "5º nível: Concentração por até 10 minutos. 6º nível: Concentração por até 1 hora. 7º nível ou superior: Concentração por até 8 horas."}, "Escudo de Fogo": {"school": "4º nível de Evocação", "time": "1 ação", "range": "Pessoal", "components": "V, G, M (um pouco de fósforo ou um vagalume)", "duration": "10 minutos", "description": ["Chamas finas e contorcidas envolvem seu corpo enquanto a magia durar, emanando luz plena em um raio de 3 metros e penumbra por mais 3 metros. Você pode encerrar a magia prematuramente usando uma ação.", "Ao conjurar a magia, escolha entre um escudo de calor ou um escudo de frio.", "Escudo de Calor. Você recebe resistência a dano de frio. Sempre que uma criatura a até 1,5 metro de você acertá-lo com um ataque corpo a corpo, ela sofre 2d8 de dano de fogo.", "Escudo de Frio. Você recebe resistência a dano de fogo. Sempre que uma criatura a até 1,5 metro de você acertá-lo com um ataque corpo a corpo, ela sofre 2d8 de dano de frio."]}, "Inseto Gigante": {"school": "4º nível de Transmutação", "time": "1 ação", "range": "9 metros", "components": "V, G", "duration": "Concentração, até 10 minutos", "description": ["Você transforma criaturas dentro do alcance em versões gigantes de suas formas naturais pela duração da magia. Você pode transformar até 10 centopeias em centopeias gigantes; até 3 aranhas em aranhas gigantes; até 5 vespas em vespas gigantes; ou 1 escorpião em um escorpião gigante.", "Cada criatura obedece aos seus comandos verbais e, em combate, age em cada um dos seus turnos. O Mestre possui as estatísticas dessas criaturas e determina suas ações e movimentos.", "Uma criatura permanece em seu tamanho gigante até a magia terminar, chegar a 0 pontos de vida ou até você usar uma ação para dissipar o efeito sobre ela.", "O Mestre pode permitir que você escolha outros tipos de insetos como alvos. Por exemplo, uma abelha transformada pode utilizar as mesmas estatísticas de uma vespa gigante."]}, "Invocar Elementais Menores": {"school": "4º nível de Conjuração", "time": "1 minuto", "range": "27 metros", "components": "V, G", "duration": "Concentração, até 1 hora", "description": ["Você invoca elementais que surgem em espaços desocupados que possa ver dentro do alcance.", "Escolha uma das seguintes opções: um elemental de ND 2 ou inferior; dois elementais de ND 1 ou inferior; quatro elementais de ND 1/2 ou inferior; oito elementais de ND 1/4 ou inferior.", "Um elemental invocado desaparece quando chega a 0 pontos de vida ou quando a magia termina.", "Os elementais são amigáveis a você e aos seus aliados. Role a iniciativa para os elementais invocados como um grupo, que possui seus próprios turnos.", "Eles obedecem aos seus comandos verbais, sem exigir uma ação sua. Se você não emitir nenhum comando, eles se defendem de criaturas hostis, mas não realizam outras ações.", "O Mestre possui as estatísticas das criaturas."], "higher": "Ao utilizar espaços de magia superiores, a quantidade de criaturas invocadas aumenta conforme descrito pela magia."}, "Invocar Seres da Floresta": {"school": "4º nível de Conjuração", "time": "1 ação", "range": "18 metros", "components": "V, G, M (uma baga de azevinho por criatura invocada)", "duration": "Concentração, até 1 hora", "description": ["Você invoca criaturas feéricas que surgem em espaços desocupados que possa ver dentro do alcance.", "Escolha uma das seguintes opções: uma criatura feérica de ND 2 ou inferior; duas criaturas feéricas de ND 1 ou inferior; quatro criaturas feéricas de ND 1/2 ou inferior; oito criaturas feéricas de ND 1/4 ou inferior.", "Uma criatura invocada desaparece quando chega a 0 pontos de vida ou quando a magia termina.", "As criaturas invocadas são amigáveis a você e aos seus aliados. Role a iniciativa para elas como um grupo, que possui seus próprios turnos.", "Elas obedecem aos seus comandos verbais, sem exigir uma ação sua. Se você não emitir nenhum comando, elas se defendem de criaturas hostis, mas não realizam outras ações.", "O Mestre possui as estatísticas das criaturas."], "higher": "A quantidade de criaturas invocadas aumenta: 6º nível: o dobro de criaturas. 8º nível: o triplo de criaturas."}, "Localizar Criatura": {"school": "4º nível de Adivinhação", "time": "1 ação", "range": "Pessoal", "components": "V, G, M (um pedaço de pele de um cão de caça)", "duration": "Concentração, até 1 hora", "description": ["Você descreve ou nomeia uma criatura que lhe seja familiar.", "Você sente a direção da localização da criatura, desde que ela esteja a até 300 metros de você. Se estiver se movendo, você também sabe a direção de seu movimento.", "A magia pode localizar uma criatura específica conhecida por você ou a criatura mais próxima de um tipo específico, como um humano ou um unicórnio, desde que você tenha visto uma criatura desse tipo de perto, a pelo menos 9 metros, ao menos uma vez.", "Se a criatura descrita ou nomeada estiver sob uma forma diferente, como sob o efeito da magia Metamorfose, esta magia não consegue localizá-la.", "A magia também não pode localizar uma criatura se houver pelo menos 3 metros de água corrente bloqueando um caminho direto entre você e ela."]}, "Metamorfose": {"school": "4º nível de Transmutação", "time": "1 ação", "range": "18 metros", "components": "V, G, M (o casulo de uma lagarta)", "duration": "Concentração, até 1 hora", "description": ["Esta magia transforma uma criatura que você possa ver dentro do alcance em uma nova forma.", "Uma criatura não voluntária deve realizar um Teste de Resistência de Sabedoria para evitar o efeito. Um metamorfo obtém sucesso automaticamente nesse teste.", "A transformação dura até o término da magia ou até o alvo chegar a 0 pontos de vida ou morrer.", "A nova forma pode ser qualquer besta cujo Nível de Desafio seja igual ou inferior ao do alvo, ou igual ou inferior ao nível do alvo caso ele não possua Nível de Desafio.", "As estatísticas de jogo do alvo, incluindo seus atributos mentais, são substituídas pelas estatísticas da besta escolhida. Ele conserva apenas seu alinhamento e personalidade.", "O alvo assume os pontos de vida da nova forma. Quando retorna à sua forma normal, volta à quantidade de pontos de vida que possuía antes da transformação.", "Se retornar à forma normal por chegar a 0 pontos de vida, qualquer dano excedente é transferido para os pontos de vida da forma original. Desde que esse dano não reduza a forma original a 0 pontos de vida, o alvo não fica inconsciente.", "As ações da criatura ficam limitadas ao que a natureza de sua nova forma permite. Ela não pode falar, conjurar magias ou realizar outras ações que exijam mãos ou fala.", "O equipamento do alvo se funde à nova forma. A criatura não pode ativar, usar, segurar ou receber benefícios de seus equipamentos."]}, "Moldar Rochas": {"school": "4º nível de Transmutação", "time": "1 ação", "range": "Toque", "components": "V, G, M (barro mole, trabalhado grosseiramente na forma desejada para o objeto de pedra)", "duration": "Instantânea", "description": ["Você toca um objeto de pedra de tamanho Médio ou menor, ou uma seção de pedra que não possua mais de 1,5 metro em qualquer dimensão, e lhe dá uma nova forma adequada ao seu propósito.", "Por exemplo, você pode moldar uma pedra grande na forma de uma arma, ídolo ou cofre, ou criar uma pequena passagem através de uma parede, desde que ela tenha menos de 1,5 metro de espessura.", "Você também pode moldar uma porta de pedra ou sua armação para selar a porta.", "O objeto criado pode possuir até duas dobradiças e uma trava, mas detalhes mecânicos pequenos não são possíveis."]}, "Movimentação Livre": {"school": "4º nível de Abjuração", "time": "1 ação", "range": "Toque", "components": "V, G, M (uma correia de couro enrolada em volta do braço ou um adorno similar)", "duration": "1 hora", "description": ["Você toca uma criatura voluntária.", "Enquanto durar a magia, o movimento do alvo não é afetado por terreno difícil, e magias e outros efeitos mágicos não podem reduzir seu deslocamento nem fazer com que ele fique paralisado ou impedido.", "O alvo também pode gastar 1,5 metro de movimento para escapar automaticamente de restrições não mágicas, como algemas ou uma criatura que o esteja agarrando.", "Além disso, estar debaixo d'água não impõe penalidades aos ataques ou movimentos do alvo."]}, "Muralha de Fogo": {"school": "4º nível de Evocação", "time": "1 ação", "range": "36 metros", "components": "V, G, M (um pequeno pedaço de fósforo)", "duration": "Concentração, até 1 minuto", "description": ["Você cria uma parede de fogo sobre uma superfície sólida dentro do alcance.", "A parede pode possuir até 18 metros de comprimento, 6 metros de altura e 30 centímetros de espessura. Alternativamente, pode criar uma parede em forma de anel com até 6 metros de diâmetro, 6 metros de altura e 30 centímetros de espessura.", "A parede é opaca e permanece até o término da magia.", "Quando a parede surge, cada criatura em sua área deve realizar um Teste de Resistência de Destreza. Em uma falha, sofre 5d8 de dano de fogo. Em um sucesso, sofre metade do dano.", "Ao conjurar a magia, você escolhe um dos lados da parede. Esse lado causa 5d8 de dano de fogo a cada criatura que terminar seu turno a até 3 metros dele ou dentro da parede.", "Uma criatura também sofre esse dano quando entra na parede pela primeira vez em um turno ou termina seu turno nela. O outro lado da parede não causa dano."], "higher": "Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, o dano aumenta em 1d8 para cada nível acima do 4º."}, "Pele Rochosa": {"school": "4º nível de Abjuração", "time": "1 ação", "range": "Toque", "components": "V, G, M (pó de diamante no valor de pelo menos 100 PO, consumido pela magia)", "duration": "Concentração, até 1 hora", "description": ["Esta magia torna a carne de uma criatura voluntária que você tocar dura como pedra.", "Até o término da magia, o alvo possui resistência a dano de concussão, perfurante e cortante não mágico."]}, "Secar": {"school": "4º nível de Necromancia", "time": "1 ação", "range": "9 metros", "components": "V, G", "duration": "Instantânea", "description": ["Energia necromântica varre uma criatura à sua escolha que você possa ver dentro do alcance, drenando seus fluidos e sua vitalidade.", "O alvo deve realizar um Teste de Resistência de Constituição. Em uma falha, sofre 8d8 de dano necrótico. Em um sucesso, sofre metade do dano.", "Esta magia não possui efeito contra mortos-vivos ou construtos.", "Se o alvo for uma criatura do tipo planta ou uma planta mágica, ele realiza o teste de resistência com desvantagem, e a magia causa dano máximo.", "Se o alvo for uma planta não mágica que não seja uma criatura, como uma árvore ou arbusto, ela não realiza teste de resistência: simplesmente seca e morre."], "higher": "Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, o dano aumenta em 1d8 para cada nível acima do 4º."}, "Tempestade Glacial": {"school": "4º nível de Evocação", "time": "1 ação", "range": "90 metros", "components": "V, G, M (uma pitada de poeira e algumas gotas de água)", "duration": "Instantânea", "description": ["Uma chuva de gelo e granizo cai contra o chão em um cilindro de 12 metros de raio e 12 metros de altura, centrado em um ponto dentro do alcance.", "Cada criatura dentro do cilindro deve realizar um Teste de Resistência de Destreza.", "Em uma falha, a criatura sofre 2d8 de dano de concussão + 4d6 de dano de frio. Em um sucesso, sofre metade do dano.", "O granizo transforma a área da tempestade em terreno acidentado até o final do seu próximo turno."], "higher": "Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, o dano de concussão aumenta em 1d8 para cada nível acima do 4º."}, "Terreno Ilusório": {"school": "4º nível de Ilusão", "time": "10 minutos", "range": "90 metros", "components": "V, G, M (uma pedra, um galho e um pedaço de planta de cor verde)", "duration": "24 horas", "description": ["Você faz com que um terreno natural em uma área equivalente a um cubo de 60 metros dentro do alcance pareça, soe e cheire como outro tipo de terreno natural.", "Campos abertos ou estradas podem ser alterados para se parecerem com um pântano, colina, fenda ou outro tipo de terreno difícil ou intransponível. Uma lagoa pode parecer um prado verdejante, ou um precipício pode parecer uma suave inclinação.", "Estruturas manufaturadas, equipamentos e criaturas não mudam de aparência.", "As características táteis do terreno permanecem inalteradas. Portanto, criaturas que entrarem na área podem perceber a ilusão ao interagir fisicamente com ela.", "Se a diferença não for óbvia pelo toque, uma criatura que examine cuidadosamente a ilusão pode realizar um teste de Inteligência (Investigação) contra sua CD de resistência à magia.", "Uma criatura que perceba a ilusão pelo que ela realmente é passa a enxergá-la como uma imagem vaga sobreposta ao terreno original."]}, "Vinhas Sufocantes": {"school": "4º nível de Conjuração", "time": "1 ação bônus", "range": "9 metros", "components": "V, G", "duration": "Concentração, até 1 minuto", "description": ["Você conjura uma vinha que brota do chão em um espaço desocupado à sua escolha que possa ver dentro do alcance.", "Quando conjura esta magia, você pode fazer a vinha atacar uma criatura que possa ver a até 9 metros dela.", "A criatura deve ser bem-sucedida em um Teste de Resistência de Destreza ou será puxada 6 metros diretamente em direção à vinha.", "Até o término da magia, você pode usar uma ação bônus em cada um dos seus turnos para fazer a vinha atacar novamente a mesma criatura ou uma criatura diferente."]}};

  const nav = document.querySelector('.main-nav');
  const navToggle = document.querySelector('[data-nav-toggle]');

  if (nav && navToggle) {
    navToggle.addEventListener('click', () => {
      const open = nav.classList.toggle('is-open');
      navToggle.setAttribute('aria-expanded', String(open));
    });
  }

  const spellModal = document.querySelector('#spell-modal');
  const modalTitle = document.querySelector('#spell-modal-title');
  const modalBody = document.querySelector('#spell-modal-body');
  const modalSubtitle = document.querySelector('#spell-modal-subtitle');

  const escapeHTML = (value = '') =>
    value.replace(/[&<>"']/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));

  const renderSpell = (name) => {
    const spell = spellDescriptions[name];

    if (!spell) {
      modalTitle.textContent = name;
      if (modalSubtitle) modalSubtitle.textContent = 'Descrição da magia';
      modalBody.innerHTML = '<p>Ainda vamos adicionar as descrições.</p>';
      return;
    }

    modalTitle.textContent = name;
    if (modalSubtitle) modalSubtitle.textContent = spell.school;

    const meta = `
      <div class="spell-meta-grid">
        <div><span>Tempo de Conjuração</span><strong>${escapeHTML(spell.time)}</strong></div>
        <div><span>Alcance</span><strong>${escapeHTML(spell.range)}</strong></div>
        <div><span>Componentes</span><strong>${escapeHTML(spell.components)}</strong></div>
        <div><span>Duração</span><strong>${escapeHTML(spell.duration)}</strong></div>
      </div>`;

    const description = spell.description
      .map((paragraph) => `<p>${escapeHTML(paragraph)}</p>`)
      .join('');

    const higher = spell.higher
      ? `<div class="higher-levels"><strong>Em Níveis Superiores.</strong><p>${escapeHTML(spell.higher)}</p></div>`
      : '';

    modalBody.innerHTML = meta + `<div class="spell-description">${description}</div>` + higher;
  };

  const closeSpellModal = () => {
    if (spellModal?.open) spellModal.close();
  };

  document.addEventListener('click', (event) => {
    const spellButton = event.target.closest('[data-spell-name]');
    if (spellButton && spellModal && modalTitle && modalBody) {
      renderSpell(spellButton.dataset.spellName || 'Magia');
      spellModal.showModal();
      return;
    }

    if (event.target.closest('[data-close-modal]')) {
      closeSpellModal();
    }
  });

  if (spellModal) {
    spellModal.addEventListener('click', (event) => {
      const rect = spellModal.getBoundingClientRect();
      const inside =
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom;

      if (!inside) closeSpellModal();
    });
  }

  const searchInput = document.querySelector('#spell-search');
  const filterButtons = [...document.querySelectorAll('[data-circle-filter]')];
  const spellCards = [...document.querySelectorAll('.spell-button')];
  const circleSections = [...document.querySelectorAll('.spell-circle-card')];
  const visibleCount = document.querySelector('#visible-spell-count');

  let activeCircle = 'all';

  const applySpellFilters = () => {
    if (!spellCards.length) return;

    const query = normalize(searchInput?.value || '');
    let shown = 0;

    spellCards.forEach((card) => {
      const matchesName = normalize(card.dataset.spellName).includes(query);
      const matchesCircle = activeCircle === 'all' || card.dataset.circle === activeCircle;
      const visible = matchesName && matchesCircle;
      card.hidden = !visible;
      if (visible) shown += 1;
    });

    circleSections.forEach((section) => {
      const hasVisible = [...section.querySelectorAll('.spell-button')].some((card) => !card.hidden);
      section.hidden = !hasVisible;
    });

    if (visibleCount) visibleCount.textContent = String(shown);
  };

  searchInput?.addEventListener('input', applySpellFilters);

  filterButtons.forEach((button) => {
    button.addEventListener('click', () => {
      activeCircle = button.dataset.circleFilter || 'all';
      filterButtons.forEach((item) => item.classList.toggle('is-active', item === button));
      applySpellFilters();
    });
  });

  applySpellFilters();
})();
